-- MySQL 8.4. Invisible rowid preserves insertion order without changing legacy insert lists.
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS courses (id CHAR(36) PRIMARY KEY, title VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS memberships (user_id CHAR(36) NOT NULL, course_id CHAR(36) NOT NULL, role VARCHAR(12) NOT NULL CHECK(role IN ('professor','student')), PRIMARY KEY(user_id,course_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS weeks (id CHAR(36) PRIMARY KEY, course_id CHAR(36) NOT NULL, week_no INTEGER NOT NULL, title VARCHAR(200) NOT NULL, UNIQUE(course_id,week_no), FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX sessions_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS materials (id CHAR(36) PRIMARY KEY, course_id CHAR(36) NOT NULL, week_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK(JSON_VALID(data)), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(week_id) REFERENCES weeks(id), INDEX materials_week(course_id,week_id), rowid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE INVISIBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS drafts (id CHAR(36) PRIMARY KEY, course_id CHAR(36) NOT NULL, week_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK(JSON_VALID(data)), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(week_id) REFERENCES weeks(id), INDEX drafts_week(course_id,week_id), rowid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE INVISIBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS quizzes (id CHAR(36) PRIMARY KEY, draft_id CHAR(36) NOT NULL UNIQUE, course_id CHAR(36) NOT NULL, week_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK(JSON_VALID(data)), FOREIGN KEY(draft_id) REFERENCES drafts(id), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(week_id) REFERENCES weeks(id), INDEX quizzes_week(course_id,week_id), rowid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE INVISIBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS attempts (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, quiz_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK(JSON_VALID(data)), UNIQUE(user_id,quiz_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(quiz_id) REFERENCES quizzes(id), rowid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE INVISIBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS jobs (id CHAR(36) PRIMARY KEY, course_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK(JSON_VALID(data)), FOREIGN KEY(course_id) REFERENCES courses(id), INDEX jobs_course(course_id), rowid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE INVISIBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS threads (id CHAR(36) PRIMARY KEY, course_id CHAR(36) NOT NULL, week_id CHAR(36) NOT NULL, student_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK(JSON_VALID(data)), CONSTRAINT clarification_once CHECK(CAST(JSON_UNQUOTE(JSON_EXTRACT(data,'$.clarification_count')) AS UNSIGNED) BETWEEN 0 AND 1), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(week_id) REFERENCES weeks(id), FOREIGN KEY(student_id) REFERENCES users(id), INDEX threads_week(course_id,week_id,student_id), rowid BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE INVISIBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS idempotency (user_id CHAR(36) NOT NULL, route VARCHAR(250) NOT NULL, `key` VARCHAR(128) NOT NULL, fingerprint CHAR(64) NOT NULL, status INTEGER NOT NULL, response LONGTEXT NOT NULL, PRIMARY KEY(user_id,route,`key`), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS auth_credentials (user_id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(300) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS course_invites (token_hash CHAR(64) PRIMARY KEY, course_id CHAR(36) NOT NULL, role VARCHAR(12) NOT NULL CHECK(role IN ('professor','student')), expires_at BIGINT NOT NULL, used_by CHAR(36) NULL, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(used_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

